<script setup lang="ts">
import {computed,ref,watch,onUnmounted,onMounted,nextTick} from 'vue';
import {definitions,initialConfig,evaluate,accepted,evidenceCards,facts,environments,commandOutput,type Config,type Result,type Event} from '../labs/workbench';
import {unitById} from '../content/curriculum';
import DiagramGlyph from './DiagramGlyph.vue';
const props=defineProps<{id:number}>();const emit=defineEmits<{complete:[]}>();
const definition=computed(()=>definitions[props.id]!);const round=ref(0),config=ref<Config>(initialConfig(props.id)),selected=ref(''),selectedRule=ref(''),message=ref('');
type Run={number:number;round:number;config:Config;result:Result;accepted:boolean;time:string};
const runs=ref<Run[]>([]),frame=ref(0),playing=ref(false),reduced=ref(false),speed=ref('1'),compare=ref(false),storageOK=ref(true);
const result=computed(()=>runs.value.filter(r=>r.round===round.value).at(-1));const previous=computed(()=>runs.value.filter(r=>r.round===round.value).at(-2));
const stale=computed(()=>result.value&&JSON.stringify(result.value.config)!==JSON.stringify(config.value));
const met=computed(()=>[0,1,2].map(i=>runs.value.some(r=>r.round===i&&r.accepted)));const allMet=computed(()=>met.value.every(Boolean));
const observed=computed(()=>stale.value?[]:result.value?.result.events.slice(0,frame.value)??[]);
watch(stale,v=>{if(v)stop();});
const canvasNodes=computed(()=>props.id===5?[...config.value.order,'response'].map(id=>definition.value.nodes.find(n=>n.id===id)!):definition.value.nodes);
const eventsFor=(id:string)=>observed.value.filter(e=>e.node===id);const state=(id:string)=>eventsFor(id).at(-1)?.status??'idle';
const active=computed(()=>observed.value.at(-1)?.node);const end=computed(()=>result.value?.result.events.length??0);
const assetState=computed(()=>{
 const run=result.value;if(!run||stale.value||!observed.value.some(e=>e.node==='data'))return ['尚未觀察','尚未觀察','尚未觀察'];
 const c=run.config,access=c.placements.access==='api';return [c.event==='read'&&!access?'內容已外洩':'內容未外洩',c.event==='edit'&&!access?'open → closed（未授權）':'open（保持原狀）',c.event==='outage'&&c.placements.failover!=='recovery'?'服務無法使用':'合法使用者可使用'];
});
const liveNode=computed(()=>definition.value.nodes.find(n=>n.id===selected.value));
const expectedEnvironment=computed(()=>round.value===0?'test':'next');
const transcript=ref<{command:string;output:string}[]>([]);
const key=()=>`security-workbench-v1-${props.id}`;
let timer:ReturnType<typeof setTimeout>|undefined;let media:MediaQueryList|undefined;
function stop(){clearTimeout(timer);playing.value=false;}
function tick(){clearTimeout(timer);if(!playing.value||frame.value>=end.value){stop();return;}timer=setTimeout(()=>{frame.value++;tick();},1000/Number(speed.value));}
function play(){if(!result.value)return;if(frame.value>=end.value)frame.value=0;playing.value=true;tick();}
function next(){stop();frame.value=Math.min(end.value,frame.value+1);}
function finishAnimation(){stop();frame.value=end.value;}
function motion(){stop();if(reduced.value)frame.value=end.value;}
function systemMotion(e:MediaQueryListEvent){reduced.value=e.matches;motion();}
onMounted(()=>{media=matchMedia('(prefers-reduced-motion: reduce)');reduced.value=media.matches;media.addEventListener('change',systemMotion);});onUnmounted(()=>{stop();media?.removeEventListener('change',systemMotion);});watch(speed,()=>{if(playing.value)tick();});
function save(){try{localStorage.setItem(key(),JSON.stringify({version:1,round:round.value,config:config.value,runs:runs.value}));}catch{storageOK.value=false;}}
function validConfig(v:any):v is Config{return v&&typeof v.actor==='string'&&typeof v.target==='string'&&typeof v.event==='string'&&v.placements&&Object.values(v.placements).every(x=>typeof x==='string')&&v.routes&&['api','batch','worker'].every(k=>['shared','direct'].includes(v.routes[k]))&&['known','order','commands','tests','priority'].every(k=>Array.isArray(v[k])&&v[k].every((x:unknown)=>typeof x==='string'))&&v.order.length===3&&new Set(v.order).size===3&&v.order.every((x:string)=>['authorize','write','notify'].includes(x))&&v.environment in environments&&v.log in environments&&typeof v.input==='string'&&typeof v.fault==='string'&&typeof v.transaction==='boolean'&&typeof v.afterCommit==='boolean';}
function load(){stop();round.value=0;config.value=initialConfig(props.id);runs.value=[];frame.value=0;selected.value=definition.value.nodes[0]!.id;selectedRule.value='';compare.value=false;transcript.value=[];message.value='';try{const raw=JSON.parse(localStorage.getItem(key())||'null');if(raw?.version===1&&[0,1,2].includes(raw.round)&&validConfig(raw.config)){round.value=raw.round;config.value=raw.config;if(Array.isArray(raw.runs)){runs.value=raw.runs.filter((r:any)=>[0,1,2].includes(r.round)&&validConfig(r.config)).slice(-120).map((r:any,i:number)=>{const out=evaluate(props.id,r.config,r.round);return {number:i+1,round:r.round,config:r.config,result:out,accepted:accepted(props.id,r.round,r.config,out),time:typeof r.time==='string'?r.time:''};});}frame.value=end.value;}}catch{storageOK.value=false;}if(allMet.value)emit('complete');}
load();watch(()=>props.id,load);watch(config,()=>{save();},{deep:true});watch(allMet,v=>{if(v)emit('complete');});
async function changeRound(i:number){stop();round.value=i;config.value=initialConfig(props.id,i);frame.value=0;selectedRule.value='';transcript.value=[];compare.value=false;message.value='';save();await nextTick();document.querySelector('.wb-heading')?.scrollIntoView({block:'start'});}
function place(node:string){selected.value=node;if(!selectedRule.value)return;if(!definition.value.slots.includes(node)){message.value='請選擇有「放置規則」標示的位置。';return;}config.value.placements[selectedRule.value]=node;message.value=`${definition.value.rules.find(r=>r.id===selectedRule.value)?.label} 已放到 ${definition.value.nodes.find(n=>n.id===node)?.label}。`;selectedRule.value='';}
function drop(e:DragEvent,node:string){const id=e.dataTransfer?.getData('text/plain');if(definition.value.rules.some(r=>r.id===id)){selectedRule.value=id!;place(node);}}
function drag(e:DragEvent,id:string){selectedRule.value=id;e.dataTransfer?.setData('text/plain',id);}
function run(){stop();const snapshot=JSON.parse(JSON.stringify(config.value)) as Config;const out=evaluate(props.id,snapshot,round.value);const record={number:(runs.value.at(-1)?.number??0)+1,round:round.value,config:snapshot,result:out,accepted:accepted(props.id,round.value,snapshot,out),time:new Date().toISOString()};runs.value.push(record);frame.value=reduced.value?out.events.length:0;selected.value=out.events[0]?.node??selected.value;message.value=record.accepted?'這次證據符合本輪目標。':'請觀察路徑與證據，再調整配置。';save();if(!reduced.value)play();}
function reset(){stop();config.value=initialConfig(props.id,round.value);selectedRule.value='';transcript.value=[];message.value='已還原本輪配置，既有證據保留。';}
function move(i:number,delta:number){if(round.value===2)return;const next=[...config.value.order];[next[i],next[i+delta]]=[next[i+delta]!,next[i]!];config.value.order=next;}
function toggleTest(t:string){config.value.tests=config.value.tests.includes(t)?config.value.tests.filter(x=>x!==t):[...config.value.tests,t];}
function environmentChanged(){config.value.commands=[];transcript.value=[];}
function command(cmd:string){transcript.value.push({command:cmd,output:commandOutput(config.value,cmd)});if(!config.value.commands.includes(cmd))config.value.commands.push(cmd);}
const rulesAt=(node:string)=>definition.value.rules.filter(r=>config.value.placements[r.id]===node);
const shownResult=computed(()=>frame.value>=end.value&&!!result.value);
const visibleChecks=computed(()=>shownResult.value?result.value!.result.checks:[]);
async function inspectNode(node:string){selected.value=node;await nextTick();document.querySelector('.wb-inspector')?.scrollIntoView({block:'center'});}
function inspect(e:Event){inspectNode(e.node);}
const changed=computed(()=>{if(!previous.value||!result.value)return [];const a=previous.value.config,b=result.value.config;return Object.keys(b).filter(k=>JSON.stringify(a[k as keyof Config])!==JSON.stringify(b[k as keyof Config]));});
const configNames:Record<string,string>={actor:'使用者',target:'案件',event:'事件',placements:'規則位置／監控',known:'已查證資訊',order:'處理順序',routes:'入口連線',input:'輸入',environment:'環境',log:'日誌',commands:'定位指令',tests:'測試集合',fault:'缺陷',transaction:'交易',afterCommit:'提交後通知',priority:'修補順序'};
function exportEvidence(){const text=`# 單元 ${unitById[props.id].number}｜${definition.value.title}\n\n${definition.value.mission}\n\n`+runs.value.map(r=>`## 第 ${r.number} 次／第 ${r.round+1} 輪\n時間：${r.time}\n配置：${JSON.stringify(r.config)}\n\n${r.result.events.map(e=>`- ${e.label}：${e.detail} ${e.data}`).join('\n')}\n\n${r.result.checks.map(c=>`- ${c.pass?'通過':'未通過'}｜${c.name}｜預期：${c.expected}｜實際：${c.actual}`).join('\n')}\n符合本輪目標：${r.accepted}`).join('\n\n')+`\n\n範圍限制：${definition.value.limit}`;const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`security-unit-${unitById[props.id].number}-simulation.md`;a.click();URL.revokeObjectURL(url);}
</script>
<template>
<section class="system-workbench" aria-label="系統互動實驗室">
<header class="wb-heading"><span class="eyebrow">SYSTEM LAB · 單元 {{unitById[id].number}}</span><h2>{{definition.title}}</h2><p>{{definition.mission}}</p></header>
<nav class="wb-rounds" aria-label="系統實驗輪次"><button v-for="(label,i) in ['觀察與基準','配置與驗證','新情境挑戰']" :key="label" :aria-current="round===i?'step':undefined" @click="changeRound(i)">{{i+1}} · {{label}} <span>{{met[i]?'✓':''}}</span></button></nav>
<div class="wb-task"><b>本輪任務</b><span>{{definition.tasks[round]}}</span><strong>{{met[round]?'已有符合目標的證據':'等待實驗證據'}}</strong></div>
<div class="wb-runbar"><button class="wb-run" @click="run">執行本輪情境與驗證</button><button @click="reset">還原本輪配置</button><button :disabled="!runs.length" @click="exportEvidence">匯出配置與證據</button><span>{{storageOK?'配置與證據保留在此瀏覽器':'無法儲存，請匯出證據'}}</span></div><p v-if="stale" class="wb-stale" role="status">配置已更新，畫布等待重新執行；下方證據保留上一次的快照。</p><div class="wb-layout">
<aside class="wb-tools" aria-label="情境與工具">
<h3>01 · 配置情境</h3>
<template v-if="id===0"><label>事件</label><div class="wb-options"><button v-for="[value,label] in [['read','未授權讀取'],['edit','未授權修改'],['outage','服務中斷']]" :key="value" :aria-pressed="config.event===value" @click="config.event=value!">{{label}}</button></div></template>
<template v-if="id===7"><label>文件情境</label><div class="wb-options"><button v-for="[value,label] in [['foreign','他人案件文件'],['large','超大文件'],['fields','管理員欄位']]" :key="value" :aria-pressed="config.event===value" @click="config.event=value!">{{label}}</button></div></template>
<template v-if="id===3"><label for="wb-actor">請求身分</label><select id="wb-actor" v-model="config.actor"><option value="alice">Alice</option><option value="bob">Bob</option><option value="guest">未登入</option></select><label for="wb-target">請求案件</label><select id="wb-target" v-model="config.target"><option value="42">42 · Alice</option><option value="73">73 · Bob</option></select><p class="wb-note">由 API 工具直接請求，可繞過前端按鈕。</p></template>
<template v-if="id===4"><div class="wb-options"><button :aria-pressed="config.input==='probe'" @click="config.input='probe'">測試輸入</button><button :aria-pressed="config.input==='normal'" @click="config.input='normal'">正常輸入</button></div><code class="wb-input">{{config.input==='probe'?"SQL: open' OR '1'='1\nHTML: <b>案件</b>":'SQL: open\nHTML: Alice'}}</code><p class="wb-note">顯示內容均為文字模擬，不執行輸入。</p></template>
<template v-if="id===6"><label for="wb-event">送入的操作</label><select id="wb-event" v-model="config.event"><option value="foreign">修改他人案件</option><option value="closed">修改已結案案件</option><option value="fields">寫入管理員欄位</option></select><p class="wb-note">本輪從{{round===2?'背景工作':'批次匯入'}}送入。驗證組也會檢查其他入口。</p></template>
<template v-if="definition.rules.length"><h3>02 · 放置保護</h3><p class="wb-note">先選規則，再點畫布位置；也可拖放。放錯位置會保留，執行後看它是否有效。</p><button v-for="rule in definition.rules" :key="rule.id" class="wb-rule" draggable="true" :aria-pressed="selectedRule===rule.id" @dragstart="drag($event,rule.id)" @click="selectedRule=selectedRule===rule.id?'':rule.id"><strong>{{rule.label}}</strong><small>{{rule.hint}}</small><span>{{config.placements[rule.id]?`已放置：${definition.nodes.find(n=>n.id===config.placements[rule.id])?.label}`:'尚未放置'}}</span></button></template>
<template v-if="id===1"><h3>查證部署快照 {{round+1}}</h3><button v-for="card in evidenceCards" :key="card.id" class="wb-rule" :aria-pressed="config.known.includes(card.id)" @click="!config.known.includes(card.id)&&config.known.push(card.id)"><strong>{{card.title}}</strong><small>{{config.known.includes(card.id)?facts(round)[card.id]:'點選打開這份證據'}}</small></button><h3>修補優先順序</h3><ol class="wb-priority"><li v-for="(service,i) in config.priority" :key="service"><b>{{i+1}}</b>服務 {{service}}<button v-if="i===1" @click="config.priority=[...config.priority].reverse()" aria-label="將第二項移到優先">移到優先 ↑</button></li></ol></template>
<template v-if="id===2"><label for="wb-environment">目前操作環境</label><select id="wb-environment" v-model="config.environment" @change="environmentChanged"><option v-for="(env,key) in environments" :key="key" :value="key">{{env.label}}</option></select><p class="wb-target-note">本輪目標：{{environments[expectedEnvironment]!.label}} / {{environments[expectedEnvironment]!.request}}</p><h3>定位與讀取</h3><button v-for="cmd in ['pwd','whoami','version','cat logs/app.log']" :key="cmd" class="wb-command" @click="command(cmd)">{{config.commands.includes(cmd)?'✓ ':''}}{{cmd}}</button><label for="wb-log">這次要引用的日誌</label><select id="wb-log" v-model="config.log"><option v-for="(env,key) in environments" :key="key" :value="key">{{env.label}} · {{env.version}} · {{env.request}}</option></select></template>
<template v-if="id===5"><p class="wb-note">固定身分 Alice、操作 PATCH 狀態 closed。只改案件編號或保護配置。</p><label for="wb-replay-target">請求案件 ID</label><select id="wb-replay-target" v-model="config.target"><option value="42">42 · 合法基準</option><option value="73">73 · 跨案件反例</option></select><button @click="config.target='73'">複製基準，只改案件 ID → 73</button><label class="wb-check"><input type="checkbox" v-model="config.transaction">啟用資料交易與拒絕回滾</label><label class="wb-check"><input type="checkbox" v-model="config.afterCommit">通知延後到成功提交後</label></template>
<template v-if="id===8"><label for="wb-fault">刻意植入缺陷</label><select id="wb-fault" v-model="config.fault"><option value="owner">移除案件權限檢查</option><option value="state">移除狀態轉移規則</option><option value="side">拒絕後仍有副作用</option><option value="both">狀態與副作用兩項缺陷</option><option value="none">正常版本</option></select><h3>選入測試案例</h3><button v-for="[value,label] in [['legal','合法更新'],['owner','跨案件拒絕'],['state','已結案拒絕'],['side','拒絕後無副作用']]" :key="value" class="wb-test-option" :aria-pressed="config.tests.includes(value!)" @click="toggleTest(value!)">{{config.tests.includes(value!)?'✓':'＋'}} {{label}}</button><template v-if="round===2"><h3>監控與處理</h3><label for="wb-signal">訊號</label><select id="wb-signal" v-model="config.placements.signal"><option value="">選擇訊號</option><option value="denied">異常大量拒絕</option><option value="views">首頁瀏覽數</option></select><label for="wb-person">處理責任</label><select id="wb-person" v-model="config.placements.person"><option value="">尚未指定</option><option value="oncall">值班維運人員</option></select><label for="wb-action">處理動作</label><select id="wb-action" v-model="config.placements.action"><option value="">尚未決定</option><option value="investigate">核對來源與版本，必要時回復</option><option value="ignore">忽略告警</option></select></template></template>
</aside>
<div class="wb-center"><div v-if="result&&!stale" class="wb-canvas-playback"><strong>動畫 {{frame}} / {{end}}</strong><button :disabled="reduced" @click="playing?stop():play()">{{playing?'暫停畫布':'播放畫布'}}</button><button :disabled="frame>=end" @click="next">畫布前進一步</button><button @click="finishAnimation">畫布顯示結果</button></div><div class="wb-canvas-head"><h3>系統圖</h3><span>{{selectedRule?'點選放置位置':'點選元件查看責任與執行資料'}}</span></div>
<div v-if="id===6" class="wb-routes"><h4>入口連線</h4><label v-for="[key,label] in [['api','單筆 API'],['batch','批次匯入'],['worker','背景工作']]" :key="key">{{label}} →<select v-model="config.routes[key!]" :aria-label="`${label}連線`"><option value="shared">共用服務 → 資料</option><option value="direct">直接寫入資料</option></select></label></div>
<div v-if="id===5" class="wb-sequence"><h4>處理順序 <small>{{round===2?'本輪固定晚檢查順序，請處理副作用':'上下移動會改變實際執行順序'}}</small></h4><div v-for="(step,i) in config.order" :key="step"><b>{{i+1}}</b><DiagramGlyph :kind="definition.nodes.find(n=>n.id===step)!.kind"/><strong>{{definition.nodes.find(n=>n.id===step)!.label}}</strong><button :disabled="i===0||round===2" :aria-label="`${definition.nodes.find(n=>n.id===step)!.label}往前移`" @click="move(i,-1)">↑</button><button :disabled="i===2||round===2" :aria-label="`${definition.nodes.find(n=>n.id===step)!.label}往後移`" @click="move(i,1)">↓</button></div><p>完成處理 → 送出回應</p></div>
<div v-if="id===0" class="wb-assets"><div v-for="(label,i) in ['C · 機密性','I · 完整性','A · 可用性']" :key="label"><b>{{label}}</b><span>{{assetState[i]}}</span></div></div>
<svg v-if="id===6" class="wb-wiring" viewBox="0 0 420 210" role="img" aria-label="三個入口依配置通過共用服務或直接寫入資料"><g v-for="(key,i) in ['api','batch','worker']" :key="key"><path :d="config.routes[key]==='shared'?`M${70+i*140} 40 Q${70+i*140} 95 210 95`:`M${70+i*140} 40 C${i===0?5:415} 50 ${i===0?5:415} 185 210 180`" :class="config.routes[key]==='shared'?'via-service':'bypass'"/><rect :x="15+i*140" y="8" width="110" height="32" rx="4"/><text :x="70+i*140" y="29">{{['單筆 API','批次匯入','背景工作'][i]}}</text></g><path d="M210 110V165" class="via-service"/><rect x="150" y="80" width="120" height="32" rx="4"/><text x="210" y="101">共用服務 ↓</text><rect x="150" y="165" width="120" height="32" rx="4"/><text x="210" y="186">資料寫入</text></svg>
<div class="wb-nodes" :style="{'--packet-time':`${1/Number(speed)}s`}" :class="{'dual-path':id===4,'multi-path':id===6}" :data-playing="playing">
<article v-for="(node,i) in canvasNodes" :key="node.id" class="wb-node" :class="[state(node.id),{selected:selected===node.id,active:active===node.id,placeable:selectedRule&&definition.slots.includes(node.id)}]" @dragover.prevent @drop.prevent="drop($event,node.id)" :data-node="node.id">
<button class="wb-node-button" :aria-label="`${definition.slots.includes(node.id)?'放置或檢視':'檢視'}：${node.label}`" :aria-pressed="selected===node.id" @click="place(node.id)"><span class="wb-zone">{{node.zone}}</span><DiagramGlyph :kind="node.kind"/><strong>{{node.label}}</strong><small>{{definition.slots.includes(node.id)?'放置規則 / 查看內容':'查看內容'}}</small></button>
<div v-if="rulesAt(node.id).length" class="wb-installed"><span v-for="rule in rulesAt(node.id)" :key="rule.id">{{rule.label}}<button :aria-label="`移除${rule.label}`" @click="delete config.placements[rule.id]">×</button></span></div>
<span class="wb-node-state">{{({idle:'尚未執行',ok:'已處理',blocked:'已攔截',bad:'觀察到問題',skipped:'未執行',info:'已到達'})[state(node.id)]}}</span>
<span v-if="i<definition.nodes.length-1&&![4,5,6,1,2].includes(id)" class="wb-connection" :class="{moving:playing&&active===node.id&&state(node.id)!=='blocked'}" aria-hidden="true">↓<i/></span>
</article></div>
<div v-if="id===4" class="wb-branch-note">外部輸入分別送往 SQL 查詢與 HTML 顯示；兩條路徑獨立處理。</div>
<div v-if="id===2" class="wb-terminal" aria-label="模擬終端"><p v-if="!transcript.length">按下左側指令，查看目前環境的輸出。</p><div v-for="(line,i) in transcript" :key="i"><strong>$ {{line.command}}</strong><pre>{{line.output}}</pre></div></div>
<aside class="wb-inspector" aria-label="元件觀察"><h4>{{liveNode?.label}}</h4><p>{{liveNode?.hint}}</p><template v-if="eventsFor(selected).length"><div v-for="(event,i) in eventsFor(selected)" :key="i"><b>{{event.label}}</b><p>{{event.detail}}</p><code v-if="event.data">{{event.data}}</code></div></template><p v-else class="wb-note">此元件尚無本次執行資料。</p></aside>
</div></div>

<p v-if="message" class="wb-message" role="status">{{message}}</p>
<section v-if="result" class="wb-results" aria-label="系統模擬證據" :data-frame="frame">
<p v-if="stale" class="wb-stale">配置已改變；以下是第 {{result.number}} 次執行快照，請重新執行。</p>
<div class="wb-playback"><strong>第 {{result.number}} 次 · {{frame}} / {{end}}</strong><button :disabled="reduced" @click="playing?stop():play()">{{playing?'暫停':frame>=end?'重播':'播放'}}</button><button :disabled="frame>=end" @click="next">逐步執行</button><button @click="finishAnimation">顯示完整證據</button><label>速度<select v-model="speed" aria-label="系統動畫速度"><option value="0.5">0.5×</option><option value="1">1×</option><option value="2">2×</option></select></label><label><input v-model="reduced" type="checkbox" @change="motion">減少動態</label></div>
<div v-if="id===5" class="wb-effects"><h4>同一請求的三條觀察線</h4><table><thead><tr><th>處理步驟</th><th>資料狀態</th><th>通知</th><th>回應</th></tr></thead><tbody><tr><td>執行前</td><td>open</td><td>尚未寄出</td><td>尚未回應</td></tr><tr v-for="(event,i) in observed" :key="i"><th>{{event.label}}</th><td>{{event.effects?.data}}</td><td>{{event.effects?.notice}}</td><td>{{event.effects?.response}}</td></tr></tbody></table></div><ol class="wb-timeline"><li v-for="(event,i) in result.result.events" :key="i" :class="frame>i?event.status:'pending'"><button @click="inspect(event)"><span>{{i+1}}</span><strong>{{event.label}}</strong><p>{{frame>i?event.detail:'等待執行'}}</p><code v-if="frame>i&&event.data">{{event.data}}</code></button></li></ol>
<template v-if="shownResult"><h3>{{result.result.summary}}</h3><p class="wb-note">下面是同一份配置的情境驗證組，包含主動畫以外的合法與違規案例。點選項目定位規則。</p><div class="wb-checks"><button v-for="check in visibleChecks" :key="check.name" :class="check.pass?'pass':'fail'" @click="inspectNode(check.node)"><strong>{{check.pass?'✓':'✕'}} {{check.name}}</strong><span>預期：{{check.expected}}</span><span>實際：{{check.actual}}</span></button></div><p class="wb-acceptance">{{result.accepted?'✓ 本次符合本輪任務。':'本次尚未符合本輪任務；請對照上方目標調整。'}}</p></template>
<button v-if="previous" class="wb-compare-toggle" @click="compare=!compare">{{compare?'收起前後對照':'比較最近兩次配置與結果'}}</button>
<div v-if="compare&&previous" class="wb-comparison"><p>變更：{{changed.length?changed.map(k=>configNames[k]??k).join('、'):'配置相同'}}。{{changed.length>1?'改了多個項目，這次差異不能歸因於單一變因。':''}}</p><article v-for="record in [previous,result]" :key="record.number"><h4>第 {{record.number}} 次</h4><p>{{record.result.summary}}</p><ul><li v-for="check in record.result.checks" :key="check.name">{{check.pass?'✓':'✕'}} {{check.name}}：{{check.actual}}</li></ul><details><summary>完整配置快照</summary><pre>{{JSON.stringify(record.config,null,2)}}</pre></details></article></div>
</section>
<div class="wb-next"><p>{{allMet?'三輪已完成。可以進入本單元的觀念檢核與應用。':`三輪進度：${met.filter(Boolean).length} / 3`}}</p><button v-if="round<2" :disabled="!met[round]" @click="changeRound(round+1)">{{round===0?'配置保護並驗證 →':'接受新情境挑戰 →'}}</button><button v-if="round>0" @click="changeRound(round-1)">← 回到前一輪</button></div>
<p class="wb-limit">模擬範圍：{{definition.limit}}</p>
</section>
</template>
